const boardEl=document.querySelector('#board');
const teams={olympus:{name:'Les Olympiens',emblem:'☼',className:'olympus'},asgard:{name:'Les Asgardiens',emblem:'ᛟ',className:'asgard'}};
const specs={pawn:{title:'Demi-dieu',glyph:'⚔'},rook:{title:'Gardien',glyph:'🏛'},knight:{title:'Guerrier',glyph:'♞'},bishop:{title:'Visionnaire',glyph:'🔱'},queen:{title:'Championne',glyph:'♛'},king:{title:'Souverain',glyph:'♚'}};
// Chaque héros possède une histoire, un pouvoir et une endurance propres.
const heroes={
'Persée':{hp:4,skill:'Reflet du bouclier',desc:'Le miroir d’Athéna détourne une attaque : frappez un ennemi et récupérez 1 PV.',mode:'enemy',range:2,damage:2,heal:1},
'Héraclès':{hp:7,skill:'Force des douze travaux',desc:'Sa force légendaire écrase un ennemi à portée de 2 cases : 4 dégâts.',mode:'enemy',range:2,damage:4},
'Achille':{hp:5,skill:'Fureur du Péléide',desc:'Une charge redoutable inflige 4 dégâts. Achille perd 1 PV en découvrant son talon.',mode:'enemy',range:3,damage:4,selfDamage:1},
'Atalante':{hp:3,skill:'Flèche de Calydon',desc:'La chasseuse atteint un ennemi jusqu’à 4 cases : 2 dégâts, même à travers les pièces.',mode:'enemy',range:4,damage:2},
'Thésée':{hp:5,skill:'Fil d’Ariane',desc:'Retrouvez votre chemin : téléportez Thésée sur une case libre à 3 cases ou moins.',mode:'empty',range:3,move:true},
'Jason':{hp:4,skill:'Toison d’or',desc:'La Toison protège un allié blessé et lui rend 3 PV.',mode:'ally',range:2,heal:3},
'Orphée':{hp:3,skill:'Chant des Enfers',desc:'Sa lyre fend les ténèbres : inflige 2 dégâts à un ennemi et soigne un allié voisin de 1 PV.',mode:'enemy',range:3,damage:2,splashHeal:1},
'Énée':{hp:5,skill:'Piété du survivant',desc:'Le héros de Troie se relève et récupère jusqu’à 3 PV.',mode:'self',range:0,heal:3},
'Héra':{hp:8,skill:'Décret de l’Olympe',desc:'La reine restaure 3 PV à un allié dans sa ligne de vue.',mode:'ally',range:4,heal:3,line:true},
'Héphaïstos':{hp:7,skill:'Forge divine',desc:'Réparez un allié proche de 2 PV ou blessez un ennemi adjacent de 2 PV.',mode:'any',range:1,damage:2,heal:2},
'Arès':{hp:6,skill:'Soif de bataille',desc:'Le dieu de la guerre frappe à 3 cases et récupère 1 PV par dégâts infligé.',mode:'enemy',range:3,damage:3,drain:true},
'Hermès':{hp:4,skill:'Sandales ailées',desc:'Le messager bondit instantanément sur une case vide à 4 cases.',mode:'empty',range:4,move:true},
'Apollon':{hp:5,skill:'Trait solaire',desc:'Une flèche de lumière inflige 3 dégâts à un ennemi aligné.',mode:'enemy',range:5,damage:3,line:true},
'Artémis':{hp:5,skill:'Lune chasseresse',desc:'La déesse inflige 2 dégâts à sa cible et aux ennemis qui la jouxtent.',mode:'enemy',range:4,damage:2,splash:1},
'Athéna':{hp:8,skill:'Égide de la stratégie',desc:'Le bouclier d’Athéna rend 2 PV à deux alliés proches.',mode:'ally',range:2,heal:2,allies:true},
'Zeus':{hp:10,skill:'Foudre du roi',desc:'Un éclair frappe un ennemi visible en ligne droite pour 4 dégâts.',mode:'enemy',range:5,damage:4,line:true},
'Sigurd':{hp:5,skill:'Lame de Gram',desc:'La lame du dragon tue en infligeant 3 dégâts et rend 1 PV à Sigurd.',mode:'enemy',range:2,damage:3,heal:1},
'Brynhild':{hp:6,skill:'Flammes de la Walkyrie',desc:'Une vague de feu inflige 2 dégâts à la cible et aux ennemis voisins.',mode:'enemy',range:3,damage:2,splash:1},
'Beowulf':{hp:7,skill:'Poigne de Grendel',desc:'Sans arme, Beowulf écrase un ennemi adjacent pour 4 dégâts.',mode:'enemy',range:1,damage:4},
'Ragnar':{hp:5,skill:'Ruse du berserker',desc:'Ragnar se blesse de 1 PV pour infliger 5 dégâts à portée de 2 cases.',mode:'enemy',range:2,damage:5,selfDamage:1},
'Sif':{hp:4,skill:'Moisson dorée',desc:'La chevelure d’or de Sif rend 3 PV à un allié sur la même rangée.',mode:'ally',range:7,heal:3,line:true},
'Leif':{hp:4,skill:'Voile du drakkar',desc:'Le navigateur disparaît et réapparaît sur une case libre à 3 cases.',mode:'empty',range:3,move:true},
'Gudrun':{hp:5,skill:'Vengeance du cycle héroïque',desc:'La vengeance inflige 3 dégâts. Si la cible tombe, Gudrun récupère 2 PV.',mode:'enemy',range:3,damage:3,killHeal:2},
'Skadi':{hp:5,skill:'Chasse au cœur de l’hiver',desc:'La déesse des neiges frappe à distance pour 2 dégâts et ralentit la cible : 1 dégât de riposte en moins.',mode:'enemy',range:4,damage:2,soften:true},
'Heimdall':{hp:8,skill:'Regard du veilleur',desc:'De son poste, il frappe un ennemi aligné jusqu’à 5 cases pour 3 dégâts.',mode:'enemy',range:5,damage:3,line:true},
'Tyr':{hp:7,skill:'Serment de la main perdue',desc:'Tyr sacrifie 1 PV pour infliger 4 dégâts à un ennemi adjacent.',mode:'enemy',range:1,damage:4,selfDamage:1},
'Thor':{hp:8,skill:'Mjöllnir, le briseur',desc:'Le marteau frappe un ennemi jusqu’à 3 cases pour 4 dégâts.',mode:'enemy',range:3,damage:4},
'Freya':{hp:7,skill:'Larmes d’ambre',desc:'Freya rend 3 PV à un allié proche, ou 2 PV à tous les alliés proches.',mode:'ally',range:2,heal:2,allies:true},
'Frigg':{hp:6,skill:'Tissage du destin',desc:'La voyante restaure 2 PV à un allié visible en diagonale ou en ligne.',mode:'ally',range:5,heal:2,line:true},
'Baldr':{hp:7,skill:'Lumière invulnérable',desc:'La lumière rend 2 PV à Baldr et 2 PV à un allié proche.',mode:'self',range:0,heal:2,supportHeal:2},
'Hel':{hp:9,skill:'Baiser de Hel',desc:'La maîtresse des morts inflige 3 dégâts et absorbe 2 PV à sa cible.',mode:'enemy',range:3,damage:3,drain:2},
'Odin':{hp:10,skill:'Ravens Huginn et Muninn',desc:'Les corbeaux guident une frappe de 3 dégâts sur tout ennemi visible en ligne droite.',mode:'enemy',range:5,damage:3,line:true,splash:1}
};
const formation={olympus:{pawn:['Persée','Héraclès','Achille','Atalante','Thésée','Jason','Orphée','Énée'],rook:['Héra','Héphaïstos'],knight:['Arès','Hermès'],bishop:['Apollon','Artémis'],queen:['Athéna'],king:['Zeus']},asgard:{pawn:['Sigurd','Brynhild','Beowulf','Ragnar','Sif','Leif','Gudrun','Skadi'],rook:['Heimdall','Tyr'],knight:['Thor','Freya'],bishop:['Frigg','Baldr'],queen:['Hel'],king:['Odin']}};
let grid=[],turn='olympus',selected=null,legal=[],skillMode=false,round=1,history=[],gameOver=false,lastMove=null,toastTimer,animating=false;
function makePiece(type,team,name){const hero=heroes[name];return{id:`${team}-${name}`,type,team,name,hp:hero.hp,maxHp:hero.hp,used:false,softened:false}}
function setup(){grid=Array.from({length:8},()=>Array(8).fill(null));for(const team of ['asgard','olympus']){const back=team==='asgard'?0:7,pawns=team==='asgard'?1:6,row=['rook','knight','bishop','queen','king','bishop','knight','rook'];row.forEach((type,c)=>grid[back][c]=makePiece(type,team,formation[team][type][type==='rook'?Math.floor(c/7):type==='knight'?(c===1?0:1):type==='bishop'?(c===2?0:1):0]));for(let c=0;c<8;c++)grid[pawns][c]=makePiece('pawn',team,formation[team].pawn[c])}
 turn='olympus';selected=null;legal=[];skillMode=false;round=1;history=[];gameOver=false;lastMove=null;animating=false;document.querySelector('#move-log').innerHTML='<li class="log-empty">Les dieux attendent votre premier coup.</li>';render()}
function inside(r,c){return r>=0&&r<8&&c>=0&&c<8}
function lineClear(r,c,nr,nc){const dr=Math.sign(nr-r),dc=Math.sign(nc-c);let y=r+dr,x=c+dc;while(y!==nr||x!==nc){if(grid[y][x])return false;y+=dr;x+=dc}return true}
function movesFor(r,c){const p=grid[r][c];if(!p)return[];const out=[];const add=(nr,nc)=>{if(!inside(nr,nc))return false;const target=grid[nr][nc];if(!target||target.team!==p.team)out.push({r:nr,c:nc,attack:!!target});return !target};const dir=p.team==='olympus'?-1:1;
 if(p.type==='pawn'){if(inside(r+dir,c)&&!grid[r+dir][c]){add(r+dir,c);const start=p.team==='olympus'?6:1;if(r===start&&!grid[r+2*dir][c])add(r+2*dir,c)}for(const dc of [-1,1])if(grid[r+dir]?.[c+dc]?.team!==p.team&&grid[r+dir]?.[c+dc])add(r+dir,c+dc)}
 else if(p.type==='knight'){for(const[dr,dc]of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]])add(r+dr,c+dc)}
 else{let dirs=[];if(['rook','queen','king'].includes(p.type))dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(['bishop','queen','king'].includes(p.type))dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dr,dc]of dirs){let nr=r+dr,nc=c+dc;while(inside(nr,nc)){const empty=add(nr,nc);if(p.type==='king'||!empty)break;nr+=dr;nc+=dc}}}return out}
function skillTargets(r,c){const p=grid[r]?.[c];if(!p||p.used)return[];const power=heroes[p.name],out=[];for(let nr=0;nr<8;nr++)for(let nc=0;nc<8;nc++){const t=grid[nr][nc],dist=Math.max(Math.abs(nr-r),Math.abs(nc-c));if(power.mode==='self'&&nr===r&&nc===c){out.push({r:nr,c:nc});continue}if(dist>power.range||nr===r&&nc===c)continue;if(power.line&&!((nr===r||nc===c||Math.abs(nr-r)===Math.abs(nc-c))&&lineClear(r,c,nr,nc)))continue;if(power.mode==='enemy'&&t?.team!==p.team&&t)out.push({r:nr,c:nc});else if(power.mode==='ally'&&t?.team===p.team&&(power.allies||t.hp<t.maxHp))out.push({r:nr,c:nc});else if(power.mode==='any'&&(!t||t.team===p.team&&t.hp<t.maxHp||t.team!==p.team))out.push({r:nr,c:nc});else if(power.mode==='empty'&&!t)out.push({r:nr,c:nc})}return out}

