function updateDetails(){const empty=document.querySelector('#empty-selection'),details=document.querySelector('#piece-details'),p=selected&&grid[selected.r][selected.c];if(!p){empty.classList.remove('hidden');details.classList.add('hidden');return}empty.classList.add('hidden');details.classList.remove('hidden');details.innerHTML=`<span class="detail-glyph ${p.team==='asgard'?'asgard':''}">${specs[p.type].glyph}</span><div class="detail-text"><div class="detail-name"></div><div class="detail-title">${specs[p.type].title} · ${teams[p.team].name} · ${heroes[p.name].skill}</div><div class="detail-meter"><i></i></div></div><div class="detail-hp"><b>${p.hp}</b>/${p.maxHp}<br>PV</div>`;details.querySelector('.detail-name').textContent=p.name;details.querySelector('.detail-meter i').style.width=`${p.hp/p.maxHp*100}%`}
function updateAbility(){const button=document.querySelector('#ability-button'),label=document.querySelector('#ability-label'),copy=document.querySelector('#ability-copy'),p=selected&&grid[selected.r][selected.c];button.classList.toggle('armed',skillMode);if(!p){button.disabled=true;label.textContent='Choisissez un héros';copy.textContent='Chaque héros possède un pouvoir unique utilisable une fois par partie.';return}const power=heroes[p.name];copy.textContent=power.desc;if(p.team!==turn||gameOver||animating){button.disabled=true;label.textContent='Attendez votre tour';return}if(p.used&&!skillMode){button.disabled=true;label.textContent='Pouvoir déjà utilisé';return}button.disabled=false;label.textContent=skillMode?'Annuler le pouvoir':power.skill}
function log(text,team=turn){if(history.length===0)document.querySelector('#move-log').innerHTML='';history.unshift({text,team});const li=document.createElement('li');li.className=team==='asgard'?'asgard-log':'';const num=document.createElement('span');num.className='log-turn';num.textContent=String(history.length).padStart(2,'0');const msg=document.createElement('span');msg.textContent=text;li.append(num,msg);document.querySelector('#move-log').prepend(li);document.querySelector('#log-count').textContent=String(history.length+1).padStart(2,'0')}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function endTurn(){skillMode=false;selected=null;legal=[];turn=turn==='olympus'?'asgard':'olympus';if(turn==='olympus')round++;render()}
function removeAt(r,c){const p=grid[r][c];grid[r][c]=null;return p}
function victory(team){gameOver=true;turn=team;toast(`${teams[team].name} remportent la bataille !`)}
function checkDeath(piece,r,c){if(piece.hp>0)return false;removeAt(r,c);log(`${piece.name} tombe au combat.`,piece.team);if(piece.type==='king'){victory(piece.team==='olympus'?'asgard':'olympus');return true}return false}
function promote(piece,r){if(piece.type==='pawn'&&(r===0||r===7)){piece.type='queen';toast(`${piece.name} s’élève au rang de champion !`)}}
function animateAttack(from,to,callback){animating=true;const source=boardEl.querySelector(`.square[data-r="${from.r}"][data-c="${from.c}"] .piece`),target=boardEl.querySelector(`.square[data-r="${to.r}"][data-c="${to.c}"]`);source?.classList.add('attack-lunge');target?.classList.add('impact-flash');setTimeout(()=>{animating=false;callback()},440)}
function normalMove(from,to){const p=grid[from.r][from.c],target=grid[to.r][to.c];if(target){animateAttack(from,to,()=>{lastMove={from,to};target.hp-=2;log(`${p.name} attaque ${target.name} : −2 PV.`);if(target.hp<=0){removeAt(to.r,to.c);grid[to.r][to.c]=p;removeAt(from.r,from.c);log(`${target.name} est vaincu.`,target.team);if(target.type==='king'){victory(p.team);render();return}promote(p,to.r)}else{const retaliation=target.softened?0:1;target.softened=false;p.hp-=retaliation;if(retaliation)log(`${target.name} résiste ; ${p.name} subit −1 PV.`);if(checkDeath(p,from.r,from.c)){render();return}}if(!gameOver)endTurn()})}else{lastMove={from,to};grid[to.r][to.c]=p;removeAt(from.r,from.c);promote(p,to.r);log(`${p.name} rejoint la case ${'abcdefgh'[to.c]}${8-to.r}.`);endTurn()}}
function applySkill(from,to){const p=grid[from.r][from.c],power=heroes[p.name],target=grid[to.r][to.c];if(!p||animating)return;const resolve=()=>{let message='';if(power.move){grid[to.r][to.c]=p;removeAt(from.r,from.c);message=`${p.name} disparaît et reparaît en ${'abcdefgh'[to.c]}${8-to.r} !`;promote(p,to.r)}else{if(power.damage&&target){target.hp-=power.damage;message=`${p.name} invoque ${power.skill} : −${power.damage} PV à ${target.name}.`;if(power.splash){for(let r=0;r<8;r++)for(let c=0;c<8;c++){const other=grid[r][c];if(other&&other!==target&&other.team!==p.team&&Math.max(Math.abs(r-to.r),Math.abs(c-to.c))<=power.splash){other.hp-=power.damage;log(`${other.name} est touché par l’effet de zone : −${power.damage} PV.`);if(other.hp<=0){removeAt(r,c);log(`${other.name} tombe au combat.`,other.team);if(other.type==='king'){victory(p.team);break}}}}}if(target.hp<=0){removeAt(to.r,to.c);log(`${target.name} tombe au combat.`,target.team);if(target.type==='king')victory(p.team);else if(power.killHeal)p.hp=Math.min(p.maxHp,p.hp+power.killHeal)}}if(power.heal){let recipients=[target].filter(Boolean);if(power.allies){recipients=[];for(let r=0;r<8;r++)for(let c=0;c<8;c++){const ally=grid[r][c];if(ally?.team===p.team&&Math.max(Math.abs(r-to.r),Math.abs(c-to.c))<=2&&ally.hp<ally.maxHp)recipients.push(ally)}recipients=recipients.slice(0,2)}for(const ally of recipients){const healed=Math.min(power.heal,ally.maxHp-ally.hp);ally.hp+=healed;if(healed)message+=` ${ally.name} récupère ${healed} PV.`}}if(power.drain){const healed=Math.min(typeof power.drain==='number'?power.drain:power.damage,p.maxHp-p.hp);p.hp+=healed;message+=` ${p.name} absorbe ${healed} PV.`}if(power.splashHeal){for(let r=0;r<8;r++)for(let c=0;c<8;c++){const ally=grid[r][c];if(ally?.team===p.team&&Math.max(Math.abs(r-to.r),Math.abs(c-to.c))<=1&&ally.hp<ally.maxHp){ally.hp=Math.min(ally.maxHp,ally.hp+power.splashHeal);message+=` ${ally.name} est apaisé.`;break}}}if(power.supportHeal){for(let r=0;r<8;r++)for(let c=0;c<8;c++){const ally=grid[r][c];if(ally&&ally!==p&&ally.team===p.team&&Math.max(Math.abs(r-from.r),Math.abs(c-from.c))<=2&&ally.hp<ally.maxHp){const healed=Math.min(power.supportHeal,ally.maxHp-ally.hp);ally.hp+=healed;message+=` ${ally.name} reçoit ${healed} PV.`;break}}}if(power.soften&&target&&target.hp>0){target.softened=true;message+=' La riposte sera amortie.'}if(power.selfDamage){p.hp-=power.selfDamage;message+=` ${p.name} sacrifie ${power.selfDamage} PV.`;if(checkDeath(p,from.r,from.c)){render();return}}}
 p.used=true;lastMove={from,to};log(message||`${p.name} invoque ${power.skill} !`);if(gameOver){render();return}endTurn()};if(power.damage&&target)animateAttack(from,to,resolve);else resolve()}

