 function animateAttack(from,to,callback){animating=true;const source=boardEl.querySelector(`.square[data-r="${from.r}"][data-c="${from.c}"] .piece`),target=boardEl.querySelector(`.square[data-r="${to.r}"][data-c="${to.c}"]`);source?.classList.add('attack-lunge');target?.classList.add('impact-flash');setTimeout(()=>{animating=false;callback()},440)}
 function normalMove(from,to){const p=grid[from.r][from.c],target=grid[to.r][to.c];if(target){animateAttack(from,to,()=>{lastMove={from,to};target.hp-=2;log(`${p.name} attaque ${target.name} : −2 PV.`);if(target.hp<=0){removeAt(to.r,to.c);grid[to.r][to.c]=p;removeAt(from.r,from.c);log(`${target.name} est vaincu.`,target.team);if(target.type==='king'){victory(p.team);render();return}promote(p,to.r)}else{const retaliation=target.softened?0:1;target.softened=false;p.hp-=retaliation;if(retaliation)log(`${target.name} résiste ; ${p.name} subit −1 PV.`);if(checkDeath(p,from.r,from.c)){render();return}}if(!gameOver)endTurn()})}else{lastMove={from,to};grid[to.r][to.c]=p;removeAt(from.r,from.c);promote(p,to.r);log(`${p.name} rejoint la case ${'abcdefgh'[to.c]}${8-to.r}.`);endTurn()}}
